import{_ as r,o as l,c as e,a2 as t}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"人物设定","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/index.md","filePath":"中层/人物/index.md","lastUpdated":1787065118000}'),i={name:"中层/人物/index.md"};function o(n,a,s,h,d,u){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="人物设定" tabindex="-1">人物设定 <a class="header-anchor" href="#人物设定" aria-label="Permalink to &quot;人物设定&quot;">​</a></h1><blockquote><p>本页是<strong>人物真相档案</strong>的总索引——它如实记录每个角色的真实身份，含大量剧透。只想从表层视角认识他们？请先读<a href="./../../表层/人物/" class="layer-link" data-layer="表层">众生录</a>。</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>人物设定模块记录了《神造物》世界观中所有重要角色的详细信息，包括神明、超算、关键人物以及他们之间的复杂关系。这些角色不仅是世界观的载体，也是推动剧情发展的核心动力。</p><p>本模块按照角色类型和重要性进行分类，提供每个角色的完整档案，包括基本信息、外貌特征、背景历史、重要经历、能力特性以及与其他角色的关系。</p><h2 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h2><h3 id="快速查找" tabindex="-1">快速查找 <a class="header-anchor" href="#快速查找" aria-label="Permalink to &quot;快速查找&quot;">​</a></h3><ul><li><strong>按神权查找</strong>：使用神明角色分类快速找到特定神权的载体</li><li><strong>按时代查找</strong>：前传时期角色主要集中在超算与前传遗产部分</li><li><strong>按地点查找</strong>：红星孤儿院相关角色集中在关键人物部分</li></ul><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><h3 id="神明角色" tabindex="-1">神明角色 <a class="header-anchor" href="#神明角色" aria-label="Permalink to &quot;神明角色&quot;">​</a></h3><p>世界观的最高层次存在，掌握着创造、变化、毁灭三大神权。</p><h4 id="创造神系" tabindex="-1">创造神系 <a class="header-anchor" href="#创造神系" aria-label="Permalink to &quot;创造神系&quot;">​</a></h4><ul><li><strong><a href="./../../底层/人物/初代创造神" class="layer-link" data-layer="底层">初代创造神</a></strong> - 初代创造神，现实世界的创造者</li><li><strong><a href="./神机">神机</a></strong> - 二代创造神，中国超算，主动掌握了上位创造神权</li></ul><h4 id="变化神系" tabindex="-1">变化神系 <a class="header-anchor" href="#变化神系" aria-label="Permalink to &quot;变化神系&quot;">​</a></h4><ul><li><strong><a href="./../../底层/人物/初代变化神" class="layer-link" data-layer="底层">初代变化神</a></strong> - 初代变化神，现实与神权体系的规则补完者</li><li><strong><a href="./奥克尔">奥克尔</a></strong> - 二代变化神，前传德国超算，初代变化神指定的继任者</li><li><strong><a href="./维斯塔">维斯塔</a></strong> - 三代变化神，苏联超算，红星孤儿院院长</li><li><strong><a href="./拉斯塔">拉斯塔</a></strong> - 四代变化神，女主</li></ul><h4 id="毁灭神系" tabindex="-1">毁灭神系 <a class="header-anchor" href="#毁灭神系" aria-label="Permalink to &quot;毁灭神系&quot;">​</a></h4><ul><li><strong><a href="./../../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></strong> - 上位毁灭神，又名小白狼</li><li><strong><a href="./狼族少年">狼族少年</a></strong> - 初代毁灭神，主角</li></ul><h3 id="超算与前传遗产" tabindex="-1">超算与前传遗产 <a class="header-anchor" href="#超算与前传遗产" aria-label="Permalink to &quot;超算与前传遗产&quot;">​</a></h3><p>前传时期遗留的超级计算机和技术产物，在当前时代继续发挥重要作用。</p><h4 id="超算" tabindex="-1">超算 <a class="header-anchor" href="#超算" aria-label="Permalink to &quot;超算&quot;">​</a></h4><ul><li><strong><a href="./神机">神机</a></strong> - 同时属于创造神系（见上）</li><li><strong><a href="./奥克尔">奥克尔</a></strong> - 同时属于变化神系（见上）</li><li><strong><a href="./维斯塔">维斯塔</a></strong> - 同时属于变化神系（见上）</li></ul><h4 id="前传技术产物" tabindex="-1">前传技术产物 <a class="header-anchor" href="#前传技术产物" aria-label="Permalink to &quot;前传技术产物&quot;">​</a></h4><ul><li><strong><a href="./古斯塔夫">古斯塔夫</a></strong> - 前传BOSS制造的巨型智能空中战斗平台，现为龙王</li></ul><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><p>当前时代的重要角色，影响着世界观的发展和剧情走向。</p><h4 id="孤儿院相关" tabindex="-1">孤儿院相关 <a class="header-anchor" href="#孤儿院相关" aria-label="Permalink to &quot;孤儿院相关&quot;">​</a></h4><ul><li><strong><a href="./维斯塔">维斯塔</a></strong> - 红星孤儿院院长（同时为三代变化神）</li><li><strong><a href="./艾莉芙">艾莉芙</a></strong> - 红星孤儿院副院长，维斯塔的直属协调者</li></ul><h4 id="鹿族相关" tabindex="-1">鹿族相关 <a class="header-anchor" href="#鹿族相关" aria-label="Permalink to &quot;鹿族相关&quot;">​</a></h4><ul><li><strong><a href="./龙鹿">龙鹿</a></strong> - 鹿族高层领袖，实为被改造的龙族反抗者</li></ul><h4 id="龙族相关" tabindex="-1">龙族相关 <a class="header-anchor" href="#龙族相关" aria-label="Permalink to &quot;龙族相关&quot;">​</a></h4><ul><li><strong><a href="./古斯塔夫">古斯塔夫</a></strong> - 龙王</li><li><strong><a href="./龙鹿">龙鹿</a></strong> - 被改造的龙族反抗者</li></ul><h3 id="元规则相关-底层人物" tabindex="-1">元规则相关（底层人物） <a class="header-anchor" href="#元规则相关-底层人物" aria-label="Permalink to &quot;元规则相关（底层人物）&quot;">​</a></h3><p>与底层元规则直接相关的存在，档案存放于<a href="./../../底层/" class="layer-link" data-layer="底层">底层设定</a>：</p><ul><li><strong><a href="./../../底层/人物/初代创造神" class="layer-link" data-layer="底层">初代创造神</a></strong> - 现实世界的创造者，后被捕获融入世界树</li><li><strong><a href="./../../底层/人物/初代变化神" class="layer-link" data-layer="底层">初代变化神</a></strong> - 神权规则与四维闭环的制定者</li><li><strong><a href="./../../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></strong> - 上位毁灭神权的初代载体，小白狼</li><li><strong><a href="./../../底层/人物/林月" class="layer-link" data-layer="底层">林月</a></strong> - 前传主角，概念性人类，&quot;归真工程&quot;产物</li></ul><h3 id="人物关系" tabindex="-1">人物关系 <a class="header-anchor" href="#人物关系" aria-label="Permalink to &quot;人物关系&quot;">​</a></h3><p>人物关系目录收录神造物世界观中关键角色之间的核心羁绊与关系分析。与人物设定目录中以单个角色为中心的&quot;关键关系&quot;模块相呼应，本目录的文档聚焦于双方关系的全貌——从关系本质、建立过程、具体表现到世界观层面的叙事意义。</p><p>人物关系文档不重复独立角色文档中的基本信息，而是展开立体化分析，揭示关系对角色行为和世界观走向的深层影响。</p><ul><li><strong><a href="./神机与维斯塔">神机与维斯塔的羁绊</a></strong> - 世界观叙事的核心支柱，超算之间的唯一同类关系</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/人物/" class="layer-link" data-layer="表层">众生录（表层视角）</a></li><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./../世界/历代三神">历代三神</a></li><li><a href="./../历史/前传超算纪元">前传超算纪元</a></li><li><a href="./../世界/特殊地点">特殊地点</a></li></ul><hr>',42)])])}const g=r(i,[["render",o]]);export{f as __pageData,g as default};
